
PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE sections(id INTEGER PRIMARY KEY,name TEXT,printed_start INTEGER,printed_end INTEGER,pdf_start INTEGER,pdf_end INTEGER,group_name TEXT);
CREATE TABLE pages(pdf_page INTEGER PRIMARY KEY,printed_page TEXT,section_id INTEGER REFERENCES sections(id),page_type TEXT,width INTEGER,height INTEGER,ocr_confidence REAL,text TEXT,flags_json TEXT);
CREATE TABLE page_sections(pdf_page INTEGER REFERENCES pages(pdf_page),section_id INTEGER REFERENCES sections(id),region TEXT,PRIMARY KEY(pdf_page,section_id));
CREATE TABLE rubrics(id INTEGER PRIMARY KEY,parent_id INTEGER REFERENCES rubrics(id),section_id INTEGER REFERENCES sections(id),depth INTEGER,label TEXT,path TEXT,text TEXT,start_pdf_page INTEGER REFERENCES pages(pdf_page),end_pdf_page INTEGER,start_line_id INTEGER,order_index INTEGER,flags_json TEXT,hierarchy_status TEXT);
CREATE TABLE lines(line_id INTEGER PRIMARY KEY,pdf_page INTEGER REFERENCES pages(pdf_page),column_index INTEGER,seq INTEGER,x0 INTEGER,y0 INTEGER,x1 INTEGER,y1 INTEGER,text TEXT,mean_confidence REAL,role TEXT,rubric_id INTEGER REFERENCES rubrics(id),dash_count INTEGER);
CREATE TABLE remedies(id INTEGER PRIMARY KEY,abbreviation TEXT,normalized TEXT,full_name TEXT,source_pdf_page INTEGER);
CREATE TABLE remedy_aliases(alias TEXT PRIMARY KEY,remedy_id INTEGER REFERENCES remedies(id),status TEXT,note TEXT);
CREATE TABLE rubric_remedies(id INTEGER PRIMARY KEY,rubric_id INTEGER REFERENCES rubrics(id),ordinal INTEGER,raw_token TEXT,remedy_id INTEGER REFERENCES remedies(id),normalized TEXT,grade INTEGER,grade_candidate INTEGER,grade_basis TEXT,source_refs_json TEXT,confidence REAL,pdf_page INTEGER REFERENCES pages(pdf_page),source_line_id INTEGER REFERENCES lines(line_id),source_provenance_status TEXT);
CREATE TABLE cross_references(id INTEGER PRIMARY KEY,rubric_id INTEGER REFERENCES rubrics(id),text TEXT,target_section_id INTEGER REFERENCES sections(id),target_printed_page INTEGER,target_rubric_id INTEGER REFERENCES rubrics(id),status TEXT);
CREATE TABLE issues(id INTEGER PRIMARY KEY,kind TEXT,severity TEXT,pdf_page INTEGER REFERENCES pages(pdf_page),rubric_id INTEGER REFERENCES rubrics(id),detail TEXT);
CREATE TABLE bibliography(source_id TEXT PRIMARY KEY,text TEXT,pdf_page INTEGER);
CREATE INDEX rubric_parent ON rubrics(parent_id,order_index);
CREATE INDEX rubric_section ON rubrics(section_id,order_index);
CREATE INDEX rubric_page ON rubrics(start_pdf_page);
CREATE INDEX remedy_normalized ON remedies(normalized);
CREATE INDEX membership_remedy ON rubric_remedies(normalized,rubric_id);
CREATE INDEX membership_rubric ON rubric_remedies(rubric_id,ordinal);
CREATE INDEX line_page ON lines(pdf_page,seq);
CREATE INDEX line_rubric ON lines(rubric_id);
CREATE INDEX issue_rubric ON issues(rubric_id);
CREATE INDEX cross_reference_rubric ON cross_references(rubric_id);
CREATE INDEX page_section_lookup ON page_sections(section_id,pdf_page);
CREATE VIRTUAL TABLE rubric_search USING fts5(path,text,content='rubrics',content_rowid='id',tokenize='unicode61 remove_diacritics 2');
CREATE VIRTUAL TABLE page_search USING fts5(text,content='pages',content_rowid='pdf_page',tokenize='unicode61 remove_diacritics 2');
CREATE VIEW rubric_tree AS SELECT r.*,s.name AS section_name,p.label AS parent_label FROM rubrics r JOIN sections s ON s.id=r.section_id LEFT JOIN rubrics p ON p.id=r.parent_id;
CREATE VIEW review_queue AS SELECT * FROM issues ORDER BY CASE severity WHEN 'high' THEN 0 WHEN 'medium' THEN 1 ELSE 2 END,pdf_page;
